@Override
public <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create a mutable mapping from vertices to vertices
    Map<V, V> vertexMapping = new HashMap<>();

    // Iterate through the vertices of the graph
    for (V vertex : graph.vertices()) {
        // Add the vertex to the mapping
        vertexMapping.put(vertex, vertex);
    }

    // Create a mutable mapping from edges to edges
    Map<E, E> edgeMapping = new HashMap<>();

    // Iterate through the edges of the graph
    for (E edge : graph.edges()) {
        // Get the source and target vertices of the edge
        V source = edge.source();
        V target = edge.target();

        // Add the edge to the mapping
        edgeMapping.put(edge, new Edge<>(source, target));
    }

    // Return the isomorphic graph mapping
    return new IsomorphicGraphMapping<>(graph, vertexMapping, edgeMapping);
}

