 */
public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Calculate the size of the string in UTF-8
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

